<h1>The AI Timeline: Research Leads, Industry Follows, Regulation Catches Up</h1>
<div class="subtitle">Key milestones across Research, Industry, and Regulation tracks (2010–2025) · Shaded bars show global private AI investment · Larger dots = critical events</div>
<div class="chart-area" id="chart"></div>

<script>
const chart = document.getElementById('chart');
const LEFT = 90, RIGHT = 1490, TOP = 40, BOTTOM = 820;
const START = 2010, END = 2025.5;

function xPos(dateStr) {
  let y, m;
  if (typeof dateStr === 'number') { y = dateStr; m = 6; }
  else { const p = dateStr.split('-'); y = +p[0]; m = p[1] ? +p[1] : 1; }
  const frac = (y + (m-1)/12 - START) / (END - START);
  return LEFT + frac * (RIGHT - LEFT);
}

// Investment bars
const investments = [
  {year:2010,v:1.3},{year:2011,v:1.9},{year:2012,v:2.5},{year:2013,v:3.2},{year:2014,v:5.5},
  {year:2015,v:8.5},{year:2016,v:12.2},{year:2017,v:18.5},{year:2018,v:28.4},{year:2019,v:32.1},
  {year:2020,v:36.5},{year:2021,v:52.8},{year:2022,v:48.2},{year:2023,v:67.2},{year:2024,v:95.8},{year:2025,v:120.5}
];
const maxInv = 120.5;
const barH = BOTTOM - TOP;
investments.forEach(d => {
  const x = xPos(d.year) - 12;
  const h = (d.v / maxInv) * barH * 0.85;
  const div = document.createElement('div');
  div.className = 'investment-bar';
  div.style.cssText = `left:${x}px;width:24px;height:${h}px;bottom:${1100-BOTTOM}px`;
  chart.appendChild(div);
  // label for select years
  if ([2010,2017,2022,2024].includes(d.year)) {
    const lbl = document.createElement('div');
    lbl.className = 'invest-label';
    lbl.style.cssText = `left:${x-4}px;bottom:${1100-BOTTOM+h+3}px`;
    lbl.textContent = `$${d.v}B`;
    chart.appendChild(lbl);
  }
});

// Year grid lines
for (let y = 2010; y <= 2025; y++) {
  const x = xPos(y);
  const line = document.createElement('div');
  line.className = 'year-line';
  line.style.cssText = `left:${x}px;top:${TOP}px;height:${BOTTOM-TOP}px`;
  chart.appendChild(line);
  const lbl = document.createElement('div');
  lbl.className = 'year-label';
  lbl.style.cssText = `left:${x}px;top:${BOTTOM+4}px`;
  lbl.textContent = y;
  chart.appendChild(lbl);
}

// Tracks
const tracks = [
  { name: 'Research', color: '#2563EB', y: TOP + 80, data: [
    {date:"2012-09",label:"AlexNet",sig:"high"},{date:"2014-06",label:"GANs",sig:"high"},
    {date:"2014-09",label:"Attention",sig:"medium"},{date:"2015-12",label:"ResNet",sig:"medium"},
    {date:"2016-03",label:"AlphaGo",sig:"critical"},{date:"2017-06",label:"Transformer",sig:"critical"},
    {date:"2018-06",label:"GPT-1",sig:"medium"},{date:"2018-10",label:"BERT",sig:"high"},
    {date:"2020-05",label:"GPT-3",sig:"critical"},{date:"2021-01",label:"DALL·E",sig:"high"},
    {date:"2022-04",label:"PaLM",sig:"medium"},{date:"2023-03",label:"GPT-4",sig:"critical"},
    {date:"2024-02",label:"Gemini 1.5",sig:"high"},{date:"2024-09",label:"o1",sig:"high"},
    {date:"2025-02",label:"Claude 3.5 /\nGPT-4.5",sig:"high"}
  ]},
  { name: 'Industry', color: '#D97706', y: TOP + 330, data: [
    {date:"2011-10",label:"Siri",sig:"high"},{date:"2014-11",label:"Alexa",sig:"high"},
    {date:"2016-09",label:"Neural\nTranslate",sig:"medium"},{date:"2018-05",label:"Duplex",sig:"medium"},
    {date:"2020-06",label:"GPT-3 API",sig:"high"},{date:"2021-06",label:"Copilot",sig:"high"},
    {date:"2022-08",label:"Stable\nDiffusion",sig:"high"},{date:"2022-11",label:"ChatGPT",sig:"critical"},
    {date:"2023-02",label:"Bing+GPT",sig:"high"},{date:"2023-07",label:"Llama 2",sig:"high"},
    {date:"2024-01",label:"AI Agents\n(Enterprise)",sig:"high"},{date:"2024-05",label:"GPT-4o",sig:"medium"},
    {date:"2025-01",label:"AI Coding\nAgents",sig:"high"}
  ]},
  { name: 'Regulation', color: '#059669', y: TOP + 580, data: [
    {date:"2016-10",label:"Obama\nAI Report",sig:"medium"},{date:"2018-04",label:"GDPR",sig:"high"},
    {date:"2019-04",label:"EU Ethics\nGuidelines",sig:"medium"},{date:"2020-02",label:"EU AI\nWhite Paper",sig:"medium"},
    {date:"2021-04",label:"EU AI Act\nProposed",sig:"high"},{date:"2022-10",label:"US AI Bill\nof Rights",sig:"medium"},
    {date:"2023-05",label:"EU AI Act\nAgreed",sig:"critical"},{date:"2023-07",label:"WH Voluntary\nCommitments",sig:"high"},
    {date:"2023-10",label:"Biden\nExec Order",sig:"critical"},{date:"2023-11",label:"Bletchley\nDeclaration",sig:"high"},
    {date:"2024-03",label:"EU AI Act\nEnacted",sig:"critical"},{date:"2024-11",label:"CA SB\n1047",sig:"high"},
    {date:"2025-02",label:"EU AI Act\nEnforced",sig:"high"}
  ]}
];

tracks.forEach(track => {
  // Track label
  const tlbl = document.createElement('div');
  tlbl.className = 'track-label';
  tlbl.style.cssText = `top:${track.y - 14}px;color:${track.color}`;
  tlbl.textContent = track.name;
  chart.appendChild(tlbl);

  // Track lane line
  const lane = document.createElement('div');
  lane.className = 'track-lane';
  lane.style.cssText = `top:${track.y}px`;
  chart.appendChild(lane);

  // Milestones
  track.data.forEach((m, i) => {
    const x = xPos(m.date);
    const isCrit = m.sig === 'critical';
    const above = i % 2 === 0;
    const dotSize = isCrit ? 16 : 10;
    const yOff = above ? -dotSize/2 : dotSize/2;

    const wrapper = document.createElement('div');
    wrapper.className = 'milestone';
    wrapper.style.cssText = `left:${x}px;top:${track.y + yOff - (above ? 0 : 0)}px`;

    if (above) {
      const lbl = document.createElement('div');
      lbl.className = 'mlabel' + (isCrit ? ' critical-text' : '');
      lbl.style.marginBottom = '3px';
      lbl.innerHTML = m.label.replace('\n','<br>');
      wrapper.appendChild(lbl);
    }

    const dot = document.createElement('div');
    dot.className = 'dot ' + (isCrit ? 'critical' : '');
    dot.style.background = track.color;
    wrapper.appendChild(dot);

    if (!above) {
      const lbl = document.createElement('div');
      lbl.className = 'mlabel' + (isCrit ? ' critical-text' : '');
      lbl.style.marginTop = '3px';
      lbl.innerHTML = m.label.replace('\n','<br>');
      wrapper.appendChild(lbl);
    }

    chart.appendChild(wrapper);
  });
});

// ChatGPT vertical line
const chatX = xPos('2022-11');
const cline = document.createElement('div');
cline.className = 'chatgpt-line';
cline.style.cssText = `left:${chatX}px;top:${TOP}px;height:${BOTTOM-TOP}px`;
chart.appendChild(cline);
const clbl = document.createElement('div');
clbl.className = 'chatgpt-label';
clbl.style.cssText = `left:${chatX+6}px;top:${TOP+2}px`;
clbl.textContent = 'ChatGPT (Nov 2022)';
chart.appendChild(clbl);

// Legend
const legend = document.createElement('div');
legend.className = 'legend';
legend.innerHTML = `
  <div class="legend-item"><span class="legend-dot" style="background:#2563EB"></span> Research</div>
  <div class="legend-item"><span class="legend-dot" style="background:#D97706"></span> Industry</div>
  <div class="legend-item"><span class="legend-dot" style="background:#059669"></span> Regulation</div>
  <div class="legend-item"><span class="legend-bar"></span> AI Investment ($B)</div>
  <div class="legend-item" style="color:#EF4444">▎ChatGPT inflection</div>
  <div class="legend-item"><span class="legend-dot" style="background:#999;width:14px;height:14px;border:2px solid #fff"></span> Critical</div>
`;
chart.appendChild(legend);

// Annotation: density
const ann = document.createElement('div');
ann.className = 'annotation';
ann.style.cssText = `right:20px;bottom:${1100-BOTTOM+30}px;text-align:right;max-width:260px`;
ann.innerHTML = 'More milestones in 2023–24<br>than the entire 2010–17 period';
chart.appendChild(ann);

// Right axis label
const rax = document.createElement('div');
rax.className = 'axis-label';
rax.style.cssText = `right:0px;bottom:${1100-BOTTOM+6}px`;
rax.textContent = 'Investment →';
chart.appendChild(rax);
</script>
</body>
</html>
